import{_ as o,o as d,c,a2 as t}from"./chunks/framework.BM5YPQmL.js";const _=JSON.parse('{"title":"架构守护脚本（维护者手册）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/release/guard-scripts.md","filePath":"zh/release/guard-scripts.md"}'),s={name:"zh/release/guard-scripts.md"};function r(a,e,l,i,n,p){return d(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="架构守护脚本-维护者手册" tabindex="-1">架构守护脚本（维护者手册） <a class="header-anchor" href="#架构守护脚本-维护者手册" aria-label="Permalink to &quot;架构守护脚本（维护者手册）&quot;">​</a></h1><p>把结构不变量变成硬失败的检查脚本。下面每个守护都按 <strong>输入 → 检查逻辑 → 失败输出 → 在哪里强制执行</strong>记录。相关 页面：<a href="./build-reference.html">build-reference</a>（承载这些守护的 规则）、<a href="./ci-gates.html">ci-gates</a>（CI 侧门禁）、 <a href="./tool-inventory.html">tool-inventory</a>（完整 tools/ 清单）。</p><p>本仓库的守护哲学：曾经在现场失败过的不变量（各节都引用了 该事故）变成一个让构建/发布失败的脚本，因此同类 bug 永远 不会再无声发布。</p><h2 id="_1-tools-check-deps-py-—-依赖方向门禁" tabindex="-1">1. tools/check_deps.py — 依赖方向门禁 <a class="header-anchor" href="#_1-tools-check-deps-py-—-依赖方向门禁" aria-label="Permalink to &quot;1. tools/check_deps.py — 依赖方向门禁&quot;">​</a></h2><p><strong>守护什么</strong>：<code>ocos/</code> 树的分层。</p><table tabindex="0"><thead><tr><th>层</th><th>不得依赖</th></tr></thead><tbody><tr><td><code>ocos/kernel/</code></td><td><code>ocos/drivers/</code>、<code>ocos/services/</code>（机制层之上的任何东西）</td></tr><tr><td><code>ocos/drivers/</code></td><td><code>ocos/services/</code></td></tr><tr><td><code>ocos/l1apps/</code></td><td><code>ocos/kernel/</code>、<code>ocos/drivers/</code>、<code>ocos/services/</code>——仅限 <code>ocos/interface/</code> 属主的头文件</td></tr></tbody></table><p><strong>输入</strong>：无（从仓库根遍历工作树）。</p><p><strong>检查逻辑</strong>：</p><ol><li>通过遍历 <code>ocos/{kernel,drivers,services,interface}</code> 中的 <code>.h</code>/<code>.c</code> 文件，构建&quot;基名 → 所属层&quot;映射。include 是纯基名， 针对这份真实清单解析——与构建的多 <code>-I</code> 策略解析它们的 方式完全一致。</li><li>对受守护层下的每个 <code>.c</code>/<code>.h</code>，读取每行 <code>#include &quot;x.h&quot;</code>（仅带引号的 include，无路径分隔符）并 针对清单解析 <code>x.h</code>。</li><li>跳过组合根：<code>kernel/core_boot_*.c</code> 按设计可以依赖每一层 （它是链条顶端）；两个注册框架按设计互相包含对方属主的 头文件。</li></ol><p><strong>失败输出</strong>（exit 1）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>check_deps: N DEPENDENCY-DIRECTION VIOLATIONS:</span></span>\n<span class="line"><span>  kernel/foo.c:12: includes &#39;bar.h&#39; -&gt; drivers/baz/bar.h (forbidden direction)</span></span></code></pre></div><p>成功时打印扫描文件数和 <code>0 violations (kernel -&gt; nothing above it; drivers -&gt; no services; l1apps -&gt; interface only)</code>。</p><p><strong>强制执行位置</strong>：手动 / 发布前卫生检查运行 （<code>python3 tools/check_deps.py</code>）。它没有接入 CI，也没有接入 <code>make</code>——在结构变更前和发布前运行它。注意 l1apps 约束已经 被构建的 <code>-I</code> 集合半强制（当应用伸出 <code>ocos/interface/</code> 之外时 编译失败）；该门禁对其做静态双重检查。</p><h2 id="_2-tools-check-bss-py-—-引导区-bss-门禁" tabindex="-1">2. tools/check_bss.py — 引导区 .bss 门禁 <a class="header-anchor" href="#_2-tools-check-bss-py-—-引导区-bss-门禁" aria-label="Permalink to &quot;2. tools/check_bss.py — 引导区 .bss 门禁&quot;">​</a></h2><p><strong>守护什么</strong>：任何常规 <code>.bss</code> 变量都不得落入引导结构区。 <code>core_boot_entry.S</code> 把页表（PML4/PDPT/PD）和引导栈保留在 <code>.bss</code> 内部；链接器会欣然把其他对象放在它们下面。WP-06b b4 会话现场抓到了后果：一个 64 KiB 的 CLI 缓冲落在了活动的 PML4 上，第一次超过 448 字节的 ISO 读取破坏了页表，引发 三重故障。</p><p><strong>输入</strong>：一个参数——已构建的 ELF（<code>check_bss.py &lt;elf&gt;</code>）。</p><p><strong>检查逻辑</strong>：</p><ol><li>运行 <code>nm -S -n &lt;elf&gt;</code>；收集每个 <code>b</code>/<code>B</code> 符号的地址和 大小（3 列行取大小 0）。</li><li>定位布局标记 <code>__boot_pml4</code>（引导区起点）、 <code>__ocse_work_start</code>、<code>__end_of_kernel</code>（WP-06c 为 GUI 向导状态加入的 <code>.ocsework</code> NOLOAD 工作区）。</li><li>任一标记缺失 → <code>FATAL: layout markers not found</code>，exit 1 （链接错误的 ELF 本身就是失败）。</li><li>符号与 <code>[__boot_pml4, __ocse_work_start)</code> 重叠且本身不是 <code>__boot_*</code>/<code>__ocse_work_start</code>/<code>__end_of_kernel</code> 标记时 即为违规。完全位于工作区内的符号是合法的（加载器经 <code>p_memsz</code> 把它清零）。</li></ol><p><strong>失败输出</strong>（exit 1）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[check_bss] FATAL: variables overlap the boot zone (0x...0..0x...1):</span></span>\n<span class="line"><span>  cli_buffer @0x...0+0x10000</span></span></code></pre></div><p>成功时打印最后一个常规变量与引导区之间的字节余量—— <code>.bss</code> 增长时要盯的数字。</p><p><strong>强制执行位置</strong>：<code>tools/build_ocse_iso.sh</code> 在打包前对 ELF 运行它——每次 <code>make ocse-iso</code> 都被门禁覆盖。未来任何溢出 都是构建错误，而不是启动期的 heisenbug。</p><h2 id="_3-tools-v2-registry-gate-py-—-v2-命令面冻结" tabindex="-1">3. tools/v2_registry_gate.py — v2 命令面冻结 <a class="header-anchor" href="#_3-tools-v2-registry-gate-py-—-v2-命令面冻结" aria-label="Permalink to &quot;3. tools/v2_registry_gate.py — v2 命令面冻结&quot;">​</a></h2><p><strong>守护什么</strong>：v2.0.0 B 组接口冻结——当收集机制本身变化时， 按声明收集的命令注册表不得变形。</p><p><strong>输入</strong>：一个参数——要启动的 ISO （<code>python3 tools/v2_registry_gate.py &lt;iso&gt;</code>）。</p><p><strong>检查逻辑</strong>（经 pexpect 启动 QEMU BIOS 512M，<code>OC_TOOLS</code> 环境变量指向迁移后的 QEMU，然后发送 <code>help -a</code>、<code>help -w</code>、 <code>help</code>）：</p><ol><li>启动到达 <code>oc&gt;</code> 提示符（TIMEOUT → <code>FAIL: no shell prompt</code>）。</li><li>注册表收集日志行 <code>registry: file-local declarations collected</code> 必须存在。</li><li><code>help -a</code> 在锚点 <code>Available commands (A-Z):</code> 和 <code>Commands by work package:</code> 之间解析——恰好 231 行命令 （233 个命令；health export/watch 计为子命令）。计数 错误 → <code>FAIL: expected 231 lines, got N</code>。</li><li><code>help -w</code> 页脚必须打印 <code>Total: 233 commands.</code>。</li><li>服务组视图必须渲染（recovery、watchdog、<code>=== l1 (</code>）。</li></ol><p><strong>失败输出</strong>：每个未通过的检查一行 <code>FAIL:</code>；完整串口日志 转储到 <code>/tmp/vcheck/v2_gate_out.txt</code> 供分诊。任一失败即 非零退出。</p><p><strong>强制执行位置</strong>：v2 时代的发布时门禁。该计数不变量在 3.x 的继任者是 31 项检查回归中的动态下限（见 <a href="./ci-gates.html">ci-gates</a> §5）：命令只能新增，不能移除——下限 从 276 起（g3 基线 275 + p0leak），当前树实测 284。</p><h2 id="_4-tools-gen-userprogs-py-—-注册约束" tabindex="-1">4. tools/gen_userprogs.py — 注册约束 <a class="header-anchor" href="#_4-tools-gen-userprogs-py-—-注册约束" aria-label="Permalink to &quot;4. tools/gen_userprogs.py — 注册约束&quot;">​</a></h2><p><strong>守护什么</strong>：内嵌 ring-3 程序注册表 （<code>ocos/kernel/userprogs_data.h</code>，由 <code>core_userprog_lookup()</code> 消费）。内核中没有任何名字是手工注册的。</p><p><strong>输入</strong>：无（从树中发现；需要 PATH 上有 <code>nasm</code> + <code>gcc</code>）。 由 <code>make userprogs</code>、<code>make all</code>（第一步）和 <code>$(USERPROGS_HDR)</code> 文件规则调用。</p><p><strong>检查逻辑 / 约束</strong>：</p><ol><li><strong>发现是机械化的</strong>：目录应用是含 <code>main.c</code> 或 <code>main.asm</code> 的 <code>ocos/l1apps/&lt;name&gt;/</code>（程序名 = 目录名；目录中每个 <code>*.c</code> 链接在一起）；遗留平铺程序是 <code>ocos/l1apps/*.{c,asm}</code>（名字 = 基名，带其 v2.x 构建模式）。 <code>_shared/</code> 是纯头文件库，永远不是应用。<code>libfoo.c</code> 走 <code>tools/build_solib.py</code>（<code>solib_data.h</code>，不是这个头文件）。 <code>ld_so.c</code> 用 <code>ld_so.ld</code> @ 0x10000000 构建。</li><li><strong>第一个动作</strong>：经 <code>gen_l1svc_ops.py</code> 再生 <code>ocos/interface/l1svc_ops.h</code>，使封装应用永远按当前 L1SVC 编号编译（只追加契约；那里失败则以 <code>gen_l1svc_ops.py failed</code> 中止）。</li><li><strong>重名即致命</strong>：目录 + 平铺程序全局 A-Z 排序后， <code>fail(&quot;duplicate program names (folder vs flat?): [...]&quot;)</code>——目录应用不得遮蔽平铺程序。</li><li><strong>严格 i18n 门禁</strong>：每个应用必须带 <code>i18n/{en,zh}.json</code> 资源（经 <code>i18n_load</code> 加载）；生成的每应用表随构建走。</li><li><strong>模式校验</strong>：<code>verify_elf()</code> 按构建模式 （exec/pie/pie-foo/ld_so）检查 <code>e_type</code>/<code>PT_INTERP</code>—— 链接错误的程序会中止生成。</li><li><strong>孤儿清除</strong>：全量再生会丢弃源已不存在的 blob（删除 应用即把它从注册表移除）。</li><li><strong>幂等产出</strong>：头文件以字节比较守护方式写入，因此未变化 的树不再生任何东西。</li></ol><p><strong>失败输出</strong>：<code>gen_userprogs: ERROR: &lt;reason&gt;</code> + exit 1 （重名、缺资源、编译/链接失败）。</p><p><strong>强制执行位置</strong>：<code>make all</code>（先重建头文件——WP06g1 catch-2 缺口）、<code>make userprogs</code>，以及接入 <code>make dist</code> 的 过期门禁 <code>make userprogs-check</code>（任一源比头文件新超过 2 秒即以 &quot;STALE embedded user programs (fix1 int3_user incident class)&quot; 消息让 dist 失败）。</p><h2 id="_5-make-reproducible-check-—-字节一致重建门禁" tabindex="-1">5. make reproducible-check — 字节一致重建门禁 <a class="header-anchor" href="#_5-make-reproducible-check-—-字节一致重建门禁" aria-label="Permalink to &quot;5. make reproducible-check — 字节一致重建门禁&quot;">​</a></h2><p><strong>守护什么</strong>：内核 ELF 的干净构建确定性（G13 门禁；ISO 级 确定性栈见下）。</p><p><strong>输入</strong>：当前树；运行两次完整子 make。</p><p><strong>检查逻辑</strong>：<code>clean</code> → <code>kernel</code> → <code>sha256sum</code> → 把 ELF 复制 到 <code>/tmp/.oc_repro_1.elf</code> → 再次 <code>clean</code> → 再次 <code>kernel</code> → <code>cmp -s</code>。目标注释核实的确定性来源：树中没有 <code>__DATE__</code>/<code>__TIME__</code>/<code>__TIMESTAMP__</code>，OCBL ISO 打包器固定每个 时间戳/GUID/卷序列号，gcc/ld 对相同输入+参数是确定性的， 链接顺序由通配展开固定，<code>strip --strip-debug</code> 移除带路径的 节，且调用方导出时尊重 <code>SOURCE_DATE_EPOCH</code>。</p><p><strong>失败输出</strong>：<code>reproducible-check: FAIL - ELF differs:</code>、 两个 SHA256、<code>cmp</code> 前 3 个差异字节，以及 <code>exit 1</code>。</p><p><strong>强制执行位置</strong>：<code>tools/build_release.sh</code> 第 2 步（FAIL 时 发布无法继续），以及发布 SOP 第 2 步（见 <a href="./process.html">process</a>）。</p><h2 id="_6-tools-fat-zero-dates-py-—-fat-日期清洗器" tabindex="-1">6. tools/fat_zero_dates.py — FAT 日期清洗器 <a class="header-anchor" href="#_6-tools-fat-zero-dates-py-—-fat-日期清洗器" aria-label="Permalink to &quot;6. tools/fat_zero_dates.py — FAT 日期清洗器&quot;">​</a></h2><p><strong>守护什么</strong>：相隔几分钟的构建之间 FAT 载荷字节一致。 <code>mformat</code>/<code>mmd</code>/<code>mcopy</code> 把当前墙上时钟盖进目录项，会把构建 时间泄漏进 ISO。</p><p><strong>输入</strong>：一个参数——mtools FAT12/16 镜像 （<code>fat_zero_dates.py &lt;img&gt;</code>；原地改写）。</p><p><strong>检查逻辑</strong>：解析 BPB（每扇区字节数、每簇扇区数、FAT 起点/大小、根目录位置）；遍历每个目录项，仅把日期/时间字段 清零——创建十分之一秒（字节 13）、创建时间（14–15）、创建 日期（16–17）、最后访问日期（18–19）、写入时间（22–23）、 写入日期（24–25）——名字、属性、簇链和文件大小不动。FAT12 链逐项跟随以遍历子目录。</p><p><strong>失败输出</strong>：设计上无（畸形镜像会抛异常）；消费该镜像的 门禁（ISO 打包器的确定性封印）会抓到下游漂移。</p><p><strong>强制执行位置</strong>：安装/更新工具链在镜像被内嵌或打包之前 使用的 FAT 镜像构建路径。它在 ISO 侧的兄弟是 <code>tools/iso_zero_ctime.py</code>（把每个 ISO9660 目录记录中的 Rock Ridge TF ctime/atime 戳改写为 1970 纪元——xorriso 把 ctime 硬编码为组装时间且 <code>-alter_date</code> 不提供 ctime 旋钮； 目录 atime 泄漏在 WP04-fix1 修复）。与打包器固定的卷日期、 节点 mtime/atime、GPT 磁盘 GUID 和 ESP 卷序列号一起，它们 构成由 <code>reproducible-check</code> + 发布 SHA256 三方检查验证的 G13 确定性栈。</p><h2 id="_7-tools-fix-file-headers-py-—-过期-file-注释改写器" tabindex="-1">7. tools/fix_file_headers.py — 过期 <code>* File:</code> 注释改写器 <a class="header-anchor" href="#_7-tools-fix-file-headers-py-—-过期-file-注释改写器" aria-label="Permalink to &quot;7. tools/fix_file_headers.py — 过期 `* File:` 注释改写器&quot;">​</a></h2><p><strong>守护什么</strong>：WP-10 project_restructure 之后的头注释真实性 ——文件移动了（如 <code>kernel/snd.c</code> → <code>drivers/snd/driver_snd.c</code>）但其 <code>* File:</code> 注释仍指向重构 前的路径。</p><p><strong>输入</strong>：无（遍历仓库）。</p><p><strong>检查逻辑</strong>：遍历每个 <code>.c</code>/<code>.h</code>/<code>.S</code>/<code>.asm</code>（跳过 <code>.git</code>、 <code>build</code>、<code>website</code>、<code>archive</code>、<code>iso</code>，以及 <code>tools/embed_grub.py</code>——它匹配到的行是它写出的模板头， 不是它自己的头）；在前 15 行内匹配 <code>^(\\s*\\*\\s*File:\\s*)(\\S+)\\s*$</code>；把路径改写为该文件在仓库中 的实际相对位置。仅注释——无语义影响。</p><p><strong>失败输出</strong>：无（卫生工具）；打印已更改 / 已正确 / 无路径 文件的清单。</p><p><strong>强制执行位置</strong>：重构后一次性运行；未来任何全树移动后 重跑它，使 <code>grep &#39;* File:&#39;</code> 保持可靠的索引。</p><h2 id="_8-门禁汇总表" tabindex="-1">8. 门禁汇总表 <a class="header-anchor" href="#_8-门禁汇总表" aria-label="Permalink to &quot;8. 门禁汇总表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>守护</th><th>输入</th><th>强制执行者</th><th>失败模式</th></tr></thead><tbody><tr><td><code>check_deps.py</code></td><td>树</td><td>手动 / 发布前</td><td>exit 1 + file:line 清单</td></tr><tr><td><code>check_bss.py</code></td><td>ELF</td><td><code>build_ocse_iso.sh</code>（每个 OCSE ISO）</td><td>exit 1 + 符号/地址清单</td></tr><tr><td><code>v2_registry_gate.py</code></td><td>ISO</td><td>发布时（v2 时代）</td><td>FAIL 行 + 非零退出</td></tr><tr><td><code>gen_userprogs.py</code> 约束</td><td>树</td><td><code>make all</code> / <code>make userprogs</code> / <code>make dist</code></td><td>带原因中止</td></tr><tr><td><code>userprogs-check</code>（make）</td><td>树</td><td><code>make dist</code></td><td>exit 1，STALE 消息</td></tr><tr><td><code>reproducible-check</code>（make）</td><td>树</td><td><code>build_release.sh</code> 第 2 步 / SOP 第 2 步</td><td>exit 1 + 差异字节</td></tr><tr><td><code>fat_zero_dates.py</code></td><td>FAT 镜像</td><td>确定性栈</td><td>下游哈希不匹配</td></tr><tr><td><code>iso_zero_ctime.py</code></td><td>ISO</td><td>确定性栈</td><td>下游哈希不匹配</td></tr><tr><td><code>fix_file_headers.py</code></td><td>树</td><td>一次性卫生检查</td><td>仅报告</td></tr><tr><td><code>ocse-vendor-check</code>（make）</td><td>树</td><td><code>make ocse-elf</code></td><td>exit 1 + 重新 vendor 指引</td></tr></tbody></table><p>vendor 侧完整性（不是脚本而是规则）：<code>ocse/</code> 只是 vendor+edits 的输出——<code>ocse-vendor-check</code> 在 <code>ocse/kernel/types.h</code> 缺失时失败，而 <code>tools/ocse_edits.py</code> 是 每个 vendored 源编辑的唯一事实来源（E1 OTA API 剥离、E2 GRUB 封装移出、E3 网络栈不 vendor、E4 崩溃管道打桩、E5 ring-3 kill 移除）。绝不手工编辑 <code>ocse/{kernel,drivers,fs,l1,boot,chinese}/*.c</code>——重新 vendor 会把它抹掉。</p>',57)])])}const h=o(s,[["render",r]]);export{_ as __pageData,h as default};
